"""AFLGo two-level distance computation for directed greybox fuzzing.

AFLGo steers the fuzzer towards a set of target basic blocks by assigning
every seed a distance to the targets. The distance is computed on two
levels and then combined:

1. Function-level distance: BFS on the *reverse* call graph starting from
   the functions that contain target blocks. A function that directly
   contains a target has distance 0, its callers distance 1, and so on.
2. Basic-block-level distance: shortest path on the CFG from each basic
   block to the nearest target block (``CFGDistance``), combined with the
   distance of the enclosing function via the harmonic mean.

The combined basic-block distances are then normalized to the [0, 1]
range (unreachable blocks map to 1.0, the maximum). A seed's distance is
the minimum block distance among the CFG edges it covers: covering even a
single block close to the target makes the whole seed "close".

The ``DistanceComputer`` class orchestrates the full pipeline and also
provides an ``accuracy`` check that validates the CFG shortest-path
component against the program's own ground-truth BFS
(``SimulatedProgram.get_shortest_distances``).
"""

from collections import deque
from typing import Dict, Iterable, List, Optional, Set, Tuple

from fuzzsim.program_model import SimulatedProgram


def harmonic_mean(values: Iterable[float]) -> float:
    """Harmonic mean of a set of distance values.

    Follows the AFLGo convention: if any value is 0 the mean is 0 (a
    target dominates the mean), and infinite values contribute
    ``1/inf = 0`` to the denominator sum (an unreachable level imposes no
    constraint). All-infinite input yields infinity.
    """
    vals = list(values)
    if not vals:
        return 0.0
    if any(v == 0.0 for v in vals):
        return 0.0
    inv_sum = sum(1.0 / v for v in vals if v != float("inf"))
    if inv_sum == 0.0:
        return float("inf")
    return len(vals) / inv_sum


class CallGraph:
    """Static call graph over the functions of a simulated program.

    Functions are named groups of basic blocks; call edges are the CFG
    edges that cross a function boundary.
    """

    def __init__(self) -> None:
        self.functions: Dict[str, Set[int]] = {}
        self.block_to_function: Dict[int, str] = {}
        self.call_edges: Set[Tuple[str, str]] = set()

    def add_function(self, name: str, blocks: Iterable[int]) -> None:
        """Register a function as a named set of basic block ids."""
        block_set = set(blocks)
        self.functions[name] = block_set
        for block_id in block_set:
            self.block_to_function[block_id] = name

    def add_call_edge(self, caller: str, callee: str) -> None:
        """Register a call edge between two known functions."""
        if caller not in self.functions or callee not in self.functions:
            raise KeyError(f"unknown function in call edge "
                           f"{caller!r} -> {callee!r}")
        if caller != callee:
            self.call_edges.add((caller, callee))

    @classmethod
    def from_program(cls, program: SimulatedProgram,
                     partition: Optional[Dict[str, List[int]]] = None
                     ) -> "CallGraph":
        """Build a call graph from a program and a function partition.

        ``partition`` maps function names to the block ids they contain.
        If omitted, every basic block becomes its own function (the call
        graph then mirrors the CFG). Call edges are inferred from CFG
        edges whose endpoints live in different functions.
        """
        graph = cls()
        if partition is None:
            partition = {f"fn_{b}": [b] for b in program.blocks}
        for name, blocks in partition.items():
            graph.add_function(name, blocks)
        for edge in program.edges:
            f_src = graph.block_to_function.get(edge.src)
            f_dst = graph.block_to_function.get(edge.dst)
            if f_src is not None and f_dst is not None and f_src != f_dst:
                graph.add_call_edge(f_src, f_dst)
        return graph

    def callees(self) -> Dict[str, List[str]]:
        """Forward adjacency: function -> functions it calls."""
        adj: Dict[str, List[str]] = {name: [] for name in self.functions}
        for caller, callee in sorted(self.call_edges):
            adj[caller].append(callee)
        return adj

    def callers(self) -> Dict[str, List[str]]:
        """Reverse adjacency: function -> functions that call it."""
        rev: Dict[str, List[str]] = {name: [] for name in self.functions}
        for caller, callee in sorted(self.call_edges):
            rev[callee].append(caller)
        return rev

    def function_distances(self, target_functions: Iterable[str]
                           ) -> Dict[str, float]:
        """Function-level distance via BFS on the reverse call graph.

        Multi-source BFS from the target functions following caller edges:
        a function's distance is the minimum number of calls needed to
        reach a target function from it. Unreachable functions get inf.
        """
        distances: Dict[str, float] = {
            name: float("inf") for name in self.functions
        }
        rev = self.callers()
        queue: deque = deque()
        for name in target_functions:
            if name in distances and distances[name] != 0.0:
                distances[name] = 0.0
                queue.append(name)
        while queue:
            node = queue.popleft()
            for caller in rev.get(node, []):
                new_dist = distances[node] + 1.0
                if new_dist < distances[caller]:
                    distances[caller] = new_dist
                    queue.append(caller)
        return distances


class CFGDistance:
    """Basic-block-level shortest-path distances on the program CFG.

    Uses BFS over reversed CFG edges from the target blocks (all edge
    weights are 1), so a block's distance is the minimum number of CFG
    edges that must be traversed to reach a target block.
    """

    def __init__(self, program: SimulatedProgram) -> None:
        self.program = program
        self._rev: Dict[int, List[int]] = {
            bid: [] for bid in program.blocks
        }
        for edge in program.edges:
            self._rev[edge.dst].append(edge.src)
        self._cache: Dict[Tuple[int, ...], Dict[int, float]] = {}

    def compute(self, target_blocks: Iterable[int]) -> Dict[int, float]:
        """Shortest distance from every block to the nearest target.

        Returns a dict mapping block id -> distance (inf if the block
        cannot reach any target). Results are cached per target set.
        """
        key = tuple(sorted(target_blocks))
        if key in self._cache:
            return self._cache[key]

        distances: Dict[int, float] = {
            bid: float("inf") for bid in self.program.blocks
        }
        queue: deque = deque()
        for block_id in key:
            if block_id in distances:
                distances[block_id] = 0.0
                queue.append(block_id)
        while queue:
            node = queue.popleft()
            for pred in self._rev.get(node, []):
                new_dist = distances[node] + 1.0
                if new_dist < distances[pred]:
                    distances[pred] = new_dist
                    queue.append(pred)
        self._cache[key] = distances
        return distances


class DistanceComputer:
    """Orchestrates AFLGo's full two-level distance pipeline.

    Parameters:
        program: the simulated target program (provides blocks/edges and
            the ground-truth ``get_shortest_distances``).
        target_blocks: basic blocks the fuzzer should be steered towards
            (defaults to ``program.target_blocks``).
        partition: optional function partition for the call graph; if
            omitted every block is its own function.

    Attributes:
        call_graph: the constructed ``CallGraph``.
        cfg_distance: the ``CFGDistance`` shortest-path component.
        function_distances: function-level distances (reverse BFS).
        bb_distances: combined raw basic-block distances (harmonic mean).
        normalized_distances: bb distances normalized to [0, 1].
    """

    def __init__(self, program: SimulatedProgram,
                 target_blocks: Optional[List[int]] = None,
                 partition: Optional[Dict[str, List[int]]] = None) -> None:
        self.program = program
        self.target_blocks = list(
            target_blocks if target_blocks is not None
            else program.target_blocks)
        self.call_graph = CallGraph.from_program(program, partition)
        self.cfg_distance = CFGDistance(program)
        self.cfg_distances = self.cfg_distance.compute(self.target_blocks)

        target_functions = {
            self.call_graph.block_to_function[b]
            for b in self.target_blocks
            if b in self.call_graph.block_to_function
        }
        self.function_distances = self.call_graph.function_distances(
            target_functions)

        self.bb_distances = self._combine_levels()
        self.normalized_distances = self._normalize(self.bb_distances)

        self._edge_by_id = {e.edge_id: e for e in program.edges}

    def _combine_levels(self) -> Dict[int, float]:
        """Combine CFG and function distances via the harmonic mean.

        Rules (per block ``m`` in function ``f``):
        - ``m`` is a target block (CFG distance 0): distance 0.
        - either level is unreachable: distance inf.
        - ``f`` is a target function (function distance 0): use the
          intra-CFG distance of ``m`` to the target block.
        - otherwise: harmonic mean of the two levels.
        """
        combined: Dict[int, float] = {}
        for block_id in self.program.blocks:
            c = self.cfg_distances.get(block_id, float("inf"))
            func = self.call_graph.block_to_function.get(block_id)
            g = self.function_distances.get(func, float("inf"))
            if c == 0.0:
                combined[block_id] = 0.0
            elif c == float("inf") or g == float("inf"):
                combined[block_id] = float("inf")
            elif g == 0.0:
                combined[block_id] = c
            else:
                combined[block_id] = harmonic_mean([c, g])
        return combined

    @staticmethod
    def _normalize(distances: Dict[int, float]) -> Dict[int, float]:
        """Normalize distances to [0, 1].

        Finite distances are min-max scaled; unreachable blocks (inf) map
        to 1.0, the maximum, so they get the lowest priority.
        """
        finite = [d for d in distances.values() if d != float("inf")]
        d_min = min(finite) if finite else 0.0
        d_max = max(finite) if finite else 0.0
        span = d_max - d_min
        normalized: Dict[int, float] = {}
        for block_id, d in distances.items():
            if d == float("inf"):
                normalized[block_id] = 1.0
            elif span > 0:
                normalized[block_id] = (d - d_min) / span
            else:
                normalized[block_id] = 0.0
        return normalized

    def block_distance(self, block_id: int,
                       normalized: bool = True) -> float:
        """Distance of a single basic block to the targets."""
        table = (self.normalized_distances if normalized
                 else self.bb_distances)
        return table.get(block_id, 1.0 if normalized else float("inf"))

    def edge_distance(self, edge_id: int,
                      normalized: bool = True) -> float:
        """Distance of a CFG edge: minimum of its two endpoint blocks."""
        edge = self._edge_by_id.get(edge_id)
        if edge is None:
            return 1.0 if normalized else float("inf")
        return min(self.block_distance(edge.src, normalized),
                   self.block_distance(edge.dst, normalized))

    def seed_distance(self, edges: Iterable[int]) -> float:
        """Seed distance: minimum block distance among covered edges.

        AFLGo assigns a seed the distance of its closest-to-target covered
        basic block, so a seed is attractive if it covers even one block
        near the targets.
        """
        best = 1.0
        for edge_id in edges:
            best = min(best, self.edge_distance(edge_id))
        return best

    def accuracy(self) -> float:
        """Percentage of blocks whose CFG distance matches ground truth.

        Validates the ``CFGDistance`` BFS component against the program's
        own ``get_shortest_distances`` (inf matches inf).
        """
        reference = self.program.get_shortest_distances(self.target_blocks)
        total = len(self.program.blocks)
        if total == 0:
            return 0.0
        matches = sum(
            1 for block_id in self.program.blocks
            if self.cfg_distances.get(block_id, float("inf"))
            == reference.get(block_id, float("inf"))
        )
        return matches / total * 100.0

