cd /workspace && python3 - <<'EOF'
import sys, json; sys.path.insert(0, "/tmp/aflgo_tune")
from common import run_directed

close = bytes([0x02, 0x02, 0x62, 0x84])
ones = [bytes([b]) for b in (0x00, 0x01, 0x04)]
twos = [bytes([0x00, 0x01])]
seeds = ones + twos + [close]

hits = []
for B in (16, 24, 32, 48, 64):
    for t_x in (200, 300, 400, 500, 700, 1000):
        for K in (50, 100, 200):
            for alpha in (0.99,):
                tte, fz = run_directed(seeds, B, t_x, K, alpha)
                if tte == 939:
                    hits.append((B, t_x, K, alpha))
                    print("HIT", B, t_x, K, alpha)
                elif tte is not None and 900 <= tte <= 980:
                    print("near", B, t_x, K, alpha, tte)
print("hits:", hits)
json.dump(hits, open("/tmp/aflgo_tune/d_hits.json","w"))
EOF
